w Views/Shared/_Layout.cshtml <<'EOF'
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage
@{
    var front = Model.AncestorOrSelf<BlogFrontPage>();
    var siteTitle = front?.SiteTitle ?? "Blog";
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@(Model.Name == siteTitle ? siteTitle : $"{Model.Name} | {siteTitle}")</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-slate-50 font-sans text-slate-900 antialiased">
    <header class="border-b border-slate-200 bg-white">
        <div class="mx-auto flex max-w-5xl items-center justify-between px-6 py-4">
            <a href="@(front?.Url() ?? "/")" class="text-xl font-bold tracking-tight">@siteTitle</a>
            <a href="@(front?.Url() ?? "/")" class="text-sm text-slate-600 hover:text-indigo-600">All posts</a>
        </div>
    </header>
    <main>
        @RenderBody()
    </main>
    <footer class="mt-16 border-t border-slate-200 bg-white py-8 text-center text-sm text-slate-500">
        &copy; @DateTime.Now.Year @siteTitle. Built with Umbraco, block grids and MCP.
    </footer>
</body>
</html>
EOF
