@inherits UmbracoViewPage<Umbraco.Bench.Umbraco.Models.BlogPost>
@{
    Layout = "_Layout.cshtml";
}
<article>
    <header class="mx-auto max-w-3xl px-6 pt-12 pb-6">
        <time datetime="@Model.PublishDate.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@Model.PublishDate.ToString("d MMMM yyyy")</time>
        <h1 class="mt-2 text-4xl font-bold tracking-tight sm:text-5xl">@Model.Name</h1>
        <p class="mt-4 text-xl text-slate-600">@Model.Summary</p>
