@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Cms.Web.Common.Routing
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<BlogPostListBlock>>
@{
    var page = Context.Features.Get<UmbracoRouteValues>()?.PublishedRequest.PublishedContent;
    var posts = (page?.Children<BlogPost>() ?? []).OrderByDescending(p => p.PublishDate);
    var max = Model.Content.MaxPosts;
    var model = new PostListModel
    {
        Heading = Model.Content.Heading,
        Posts = (max > 0 ? posts.Take(max) : posts)
            .Select(p => new PostCardModel
            {
                Title = p.Name,
                Summary = p.Summary ?? "",
                Url = p.Url(),
                ImageUrl = p.HeroImage?.GetCropUrl(width: 800, height: 450),
                Date = p.PublishDate,
            })
            .ToList(),
    };
}
@await Component.InvokeAsync("BlogPostList", new { model })
EOF

