@using Umbraco.Bench.Umbraco.Models.Blocks
@model PostListModel
<section class="mx-auto max-w-5xl px-6 py-14">
    @if (!string.IsNullOrWhiteSpace(Model.Heading))
    {
        <h2 class="mb-8 text-3xl font-bold text-slate-900">@Model.Heading</h2>
    }
    <div class="grid gap-8 sm:grid-cols-2">
        @foreach (var post in Model.Posts)
        {
            <a href="@post.Url" class="group overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:shadow-lg">
                @if (!string.IsNullOrEmpty(post.ImageUrl))
                {
                    <img src="@post.ImageUrl" alt="" class="aspect-video w-full object-cover" />
                }
                <div class="p-6">
                    <time datetime="@post.Date.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.Date.ToString("d MMMM yyyy")</time>
                    <h3 class="mt-2 text-xl font-semibold text-slate-900 group-hover:text-indigo-600">@post.Title</h3>
                    <p class="mt-3 text-slate-600">@post.Summary</p>
                </div>
            </a>
        }
    </div>
</section>

