for p in one-protocol-to-connect-them-all building-a-cms-site-by-conversation; do curl -sk https://localhost:44317/$p/ -o /tmp/$p.html -w "$p %{http_code}
"; echo " fallbacks: $(grep -c 'Could not render' /tmp/$p.html)  h2: $(grep -c '<h2' /tmp/$p.html)  blockquote: $(grep -c '<blockquote' /tmp/$p.html)  figure: $(grep -c '<figure' /tmp/$p.html)"; done
for u in $(grep -oE 'src="/media[^"]*"' /tmp/one-protocol-to-connect-them-all.html | sed 's/src="//;s/"$//;s/&amp;/\&/g'); do curl -sk -o /dev/null -w "%{http_code} %{content_type}
" "https://localhost:44317$u"; done
curl -sk -o /dev/null -w "css %{http_code}
" https://localhost:44317/dist/site.css

